"""Locate a usable fastText engine and expose train()/test() that forward arguments verbatim.

Preference order (recorded in `ENGINE`/`ENGINE_INFO` so metrics.json can state provenance):
  1. an already-importable `fasttext` module (the authors' official python binding,
     i.e. the same C++ implementation as src/ in the paper's repo),
  2. `pip install fasttext-wheel` (prebuilt wheel of the same 0.9.2 code),
  3. the authors' native build (`make` + ./fasttext binary, or `pip install .` from repo/),
  4. documented fallback: the authors' PyTorch EmbeddingBag example
     (python/doc/examples/FastTextEmbeddingBag.py) -> a re-implementation, which caps the
     verdict at partially_reproduced.
"""

import os
import subprocess
import sys

ENGINE = None            # "fasttext-module" | "native-binary" | "embeddingbag"
ENGINE_INFO = {}


# ------------------------------------------------------------------ discovery helpers
def _try_import_fasttext():
    try:
        import fasttext  # noqa: F401
    except Exception as e:  # noqa: BLE001
        return None, str(e)
    return fasttext, getattr(fasttext, "__version__", "unknown")


def _pip_install(pkg):
    try:
        r = subprocess.run([sys.executable, "-m", "pip", "install", pkg],
                           capture_output=True, text=True, timeout=420)
        return r.returncode == 0
    except Exception:  # noqa: BLE001
        return False


def _find_native_binary():
    for cand in ("fasttext.exe", "fasttext"):
        p = os.path.join("repo", cand)
        if os.path.isfile(p):
            return p
    return None


# ------------------------------------------------------------------ engine: official binding
class _ModuleEngine:
    name = "fasttext-module"

    def __init__(self, module):
        self.ft = module
        self.version = getattr(module, "__version__", "unknown")

    def train(self, input_path, output_path, **kwargs):
        # fastText's python API appends .bin to `output`; pass the stem through unchanged.
        return self.ft.train_supervised(input=input_path, output=output_path, **kwargs)

    def test(self, model, test_path):
        return model.test(test_path)          # -> (N, P@1, R@1)

    def words(self, model):
        return model.words


class _EmbeddingBagEngine:
    """Fallback: the authors' own PyTorch EmbeddingBag re-implementation of fastText."""
    name = "embeddingbag-fallback"

    def __init__(self, mod):
        self.mod = mod

    def train(self, input_path, output_path, **kwargs):
        return self.mod.train(input_path, output_path, **kwargs)

    def test(self, model, test_path):
        return self.mod.test(model, test_path)


# ------------------------------------------------------------------ public API
def get_engine(prefer=None, verbose=True):
    """Return (engine, info) and cache module-level ENGINE/ENGINE_INFO."""
    global ENGINE, ENGINE_INFO
    if ENGINE is not None and prefer is None:
        return ENGINE, ENGINE_INFO

    tried = []
    # 1. already importable
    mod, info = _try_import_fasttext()
    if mod is not None:
        ENGINE, ENGINE_INFO = _ModuleEngine(mod), {"detail": f"import fasttext ok ({info})"}
        if verbose:
            print("Engine: official fastText python binding (already importable):", info)
        return ENGINE, ENGINE_INFO
    tried.append(f"import fasttext: {info}")

    # 2. prebuilt wheel of the same code
    for pkg in ("fasttext-wheel", "fasttext"):
        if _pip_install(pkg):
            mod, info = _try_import_fasttext()
            if mod is not None:
                ENGINE, ENGINE_INFO = _ModuleEngine(mod), {"detail": f"pip install {pkg} ok"}
                if verbose:
                    print(f"Engine: official fastText python binding (pip install {pkg})")
                return ENGINE, ENGINE_INFO
        tried.append(f"pip install {pkg}: failed")

    # 3. native binary from the authors' repo
    binp = _find_native_binary()
    if binp:
        ENGINE = _NativeEngine(binp)
        ENGINE_INFO = {"detail": binp}
        return ENGINE, ENGINE_INFO
    tried.append("native binary: not found")

    # 4. EmbeddingBag re-implementation (authors' example), if torch is available
    try:
        sys.path.insert(0, os.path.join("repo", "python", "doc", "examples"))
        import FastTextEmbeddingBag as _emb  # noqa: E402
        ENGINE = _EmbeddingBagEngine(_emb)
        ENGINE_INFO = {"detail": "repo/python/doc/examples/FastTextEmbeddingBag.py",
                       "verdict_ceiling": "partially_reproduced"}
        if verbose:
            print("Engine: authors' PyTorch EmbeddingBag example (RE-IMPLEMENTATION)")
        return ENGINE, ENGINE_INFO
    except Exception as e:  # noqa: BLE001
        tried.append(f"embeddingbag example: {e}")

    raise RuntimeError("No usable fastText engine.\n  " + "\n  ".join(tried))


class _NativeEngine:
    """Wrapper around the compiled ./fasttext binary (same C++ code as the binding)."""

    name = "native-binary"

    def __init__(self, path):
        self.path = path

    def train(self, input_path, output_path, **kwargs):
        cmd = [self.path, "supervised", "-input", input_path, "-output", output_path]
        flag = {"wordNgrams": "wordNgrams", "minCount": "minCount", "lrUpdateRate": "lrUpdateRate",
                "minn": "minn", "maxn": "maxn"}
        for k, v in kwargs.items():
            if v is None:
                continue
            cmd += ["-" + flag.get(k, k), str(v)]
        subprocess.run(cmd, check=True, capture_output=True, text=True)
        return output_path + ".bin"

    def test(self, model, test_path):
        out = subprocess.run([self.path, "test", model, test_path],
                             check=True, capture_output=True, text=True).stdout
        parts = out.split()
        return int(parts[1]), float(parts[3]), float(parts[5])

